package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class TaskBatchServiceTest {
 static Map<String,Object> step(String key){var a=new LinkedHashMap<>(TaskSessionServiceTest.action());a.put("idempotency_key",key);return Map.of("step_key",key,"tool","edt_form_action","arguments",a,"expect",TaskSessionServiceTest.expect());}
 @Test public void completedBatchPersistsAndNeverReplays()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();b.done=true;var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"batch").get("session_id");var plan=List.of(step("one"),step("two"));assertEquals("completed",s.batchAdvance(id,"b",plan,2000).get("state"));assertEquals(2,b.actions);assertEquals("completed",new TaskSessionService(f.path,b).batchAdvance(id,"b",plan,2000).get("state"));assertEquals(2,b.actions);assertThrows(IllegalStateException.class,()->s.batchAdvance(id,"b",List.of(step("changed")),2000));}}
 @Test public void timeoutAndStatusNeverDispatchNextStep()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"batch-running").get("session_id");var plan=List.of(step("one"),step("two"));assertEquals("running",s.batchAdvance(id,"b",plan,0).get("state"));assertEquals(1,b.actions);b.done=true;assertEquals("pending",s.batchStatus(id,"b").get("state"));assertEquals(1,b.actions);assertEquals("completed",s.batchAdvance(id,"b",plan,2000).get("state"));assertEquals(2,b.actions);}}
 @Test public void falsePostconditionStopsBeforeNextAction()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();b.done=true;b.condition=false;var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"batch-false").get("session_id");assertEquals("failed",s.batchAdvance(id,"b",List.of(step("one"),step("two")),2000).get("state"));assertEquals(1,b.actions);}}
 @Test public void unknownOutcomeIsDurableAndCannotBeRetried()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();b.fail=true;var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"batch-unknown").get("session_id");var plan=List.of(step("one"),step("two"));assertEquals("outcome_unknown",s.batchAdvance(id,"b",plan,2000).get("state"));b.fail=false;assertEquals("outcome_unknown",new TaskSessionService(f.path,b).batchAdvance(id,"b",plan,2000).get("state"));assertEquals(1,b.actions);assertThrows(IllegalStateException.class,()->s.preview(id));}}
 @Test public void preflightChecksEntirePlanBeforeAnyAction()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"bad-plan").get("session_id");assertThrows(IllegalArgumentException.class,()->s.batchAdvance(id,"b",List.of(step("same"),step("same")),100));assertThrows(IllegalArgumentException.class,()->s.batchAdvance(id,"b",List.of(step("one"),Map.of("step_key","two","tool","edt_form_action","arguments",TaskSessionServiceTest.action())),100));assertEquals(0,b.actions);}}
 @Test public void driftBlocksContinuationAndResumeIsHistorical()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"resume").get("session_id");s.batchAdvance(id,"b",List.of(step("one")),0);b.base="changed";assertThrows(IllegalStateException.class,()->s.batchAdvance(id,"b",List.of(step("one")),100));var out=new TaskSessionService(f.path,b).resume(id,0,20);assertEquals(false,out.get("binding_current"));assertEquals(true,out.get("observations_are_historical"));assertEquals(1,b.actions);assertEquals(1,((List<?>)out.get("steps")).size());}}

 @Test public void batchNeverBypassesRequiredLiveClientVerification()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"verify-required",true).get("session_id");var out=s.batchAdvance(id,"b",List.of(step("one")),0);assertEquals("blocked",out.get("state"));assertEquals(0,b.actions);}}
 @Test public void hostLifecycleIsNotMistakenForVerifiedBatchCompletion()throws Exception{try(var f=new TestDataLedgerTest.Fixture()){var b=new TaskSessionServiceTest.Backend();var s=new TaskSessionService(f.path,b);String id=(String)s.open("P",null,null,"host-not-batch").get("session_id");assertThrows(IllegalArgumentException.class,()->s.batchAdvance(id,"b",List.of(Map.of("step_key","host","tool","edt_runtime_host","arguments",Map.of("action","start","host_id","own"))),0));assertEquals(0,b.actions);}}
}
